        width: min(100%, 30rem);
        padding: clamp(1.25rem, 6vw, 2.5rem);
        border: 1px solid var(--border);
        border-radius: 1.5rem;
        background: linear-gradient(145deg, var(--panel), var(--panel-strong));
        box-shadow: 0 1.5rem 4rem var(--shadow);
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(2rem, 10vw, 3rem);
        line-height: 1;
        letter-spacing: -0.04em;
      }

      .intro {
        margin: 0 0 2rem;
        color: var(--muted);
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
        padding: 1rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: #10182b;
      }

      .checkbox-row {
        display: flex;
        align-items: flex-start;
        gap: 0.75rem;
      }

      input[type="checkbox"] {
        width: 1.35rem;
        height: 1.35rem;
        flex: 0 0 auto;
        margin: 0.12rem 0 0;
        accent-color: var(--accent-strong);
      }

      input[type="checkbox"]:focus-visible,
      button:focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 3px var(--bg), 0 0 0 6px var(--accent);
      }

      label {
        color: var(--text);
        font-weight: 700;
