        font-weight: 800;
        cursor: pointer;
      }

      button:hover {
        background: var(--accent);
      }

      button:active {
        transform: translateY(1px);
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--success);
        font-weight: 700;
      }

      @media (forced-colors: active) {
        body,
