   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content">
       <div id="app"></div>
     </main>

     <script>
       const CheckboxField = () => `
         <div class="form-field">
           <div class="checkbox-row">
             <input
               type="checkbox"
               id="terms-consent"
               name="termsConsent"
               required
               aria-describedby="terms-consent-helper form-status"
             >
             <label for="terms-consent">
               I agree to the terms of use <span class="required" aria-hidden="true">*</span>
             </label>
           </div>
           <p class="helper" id="terms-consent-helper">
             Required to continue. Review the terms before submitting.
           </p>
         </div>
       `;

       const ConsentForm = () => `
         <section class="card" aria-labelledby="page-title">
           <h1 id="page-title">Terms consent</h1>
           <p class="intro">Confirm your agreement to continue.</p>
           <form id="consent-form">
             ${CheckboxField()}
             <button type="submit">Submit agreement</button>
             <p class="status" id="form-status" aria-live="polite"></p>
           </form>
         </section>
       `;

       const render = (component, target) => {
         target.innerHTML = component();
       };

       render(ConsentForm, document.getElementById("app"));

       const form = document.getElementById("consent-form");
       const checkbox = document.getElementById("terms-consent");
       const status = document.getElementById("form-status");

       checkbox.addEventListener("invalid", () => {
         checkbox.setAttribute("aria-invalid", "true");
         status.textContent = "Please agree to the terms of use before submitting.";
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         checkbox.removeAttribute("aria-invalid");
         status.textContent = "Agreement submitted.";
       });

       checkbox.addEventListener("change", () => {
         if (checkbox.checked) {
           checkbox.removeAttribute("aria-invalid");
           status.textContent = "";
         }
       });
     </script>
   </body>
 </html>

